import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

function invalid(message) {
  throw new Error(message);
}

/**
 * Select complete, framed context sections within a UTF-8 byte budget.
 *
 * @param {Array<{id:string,text:string,priority:number,required:boolean}>} sections
 * @param {number} maxBytes
 * @returns {{text:string,bytes:number,included:string[],omitted:string[]}}
 */
export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    invalid('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    invalid('sections must be an array');
  }

  const seenIds = new Set();
  const validated = [];
  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) {
      invalid(`sections must be dense (missing index ${index})`);
    }
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      invalid(`section at index ${index} must be a non-null, non-array object`);
    }
    if (typeof section.id !== 'string' || section.id.length === 0) {
      invalid(`section at index ${index} has an invalid id`);
    }
    if (seenIds.has(section.id)) {
      invalid(`duplicate section id: ${JSON.stringify(section.id)}`);
    }
    if (typeof section.text !== 'string') {
      invalid(`section at index ${index} has invalid text`);
    }
    if (!Number.isSafeInteger(section.priority) || section.priority < 0) {
      invalid(`section at index ${index} has invalid priority`);
    }
    if (typeof section.required !== 'boolean') {
      invalid(`section at index ${index} has invalid required flag`);
    }

    seenIds.add(section.id);
    const frame = `### ${JSON.stringify(section.id)}\n${section.text}\n`;
    validated.push({
      id: section.id,
      priority: section.priority,
      required: section.required,
      index,
      frame,
      bytes: Buffer.byteLength(frame, 'utf8')
    });
  }

  const required = validated.filter((section) => section.required);
  const requiredBytes = required.reduce((total, section) => total + section.bytes, 0);
  if (requiredBytes > maxBytes) {
    invalid('required sections exceed maxBytes');
  }

  const optional = validated
    .filter((section) => !section.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);
  const selected = [...required];
  let bytes = requiredBytes;
  const includedOptional = new Set();
  for (const section of optional) {
    if (section.bytes <= maxBytes - bytes) {
      selected.push(section);
      includedOptional.add(section.index);
      bytes += section.bytes;
    }
  }

  return {
    text: selected.map((section) => section.frame).join(''),
    bytes,
    included: selected.map((section) => section.id),
    omitted: validated
      .filter((section) => !section.required && !includedOptional.has(section.index))
      .map((section) => section.id)
  };
}

function runCli() {
  try {
    if (process.argv.length !== 3) {
      invalid('usage: node context-packet.js INPUT_JSON_FILE');
    }
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      invalid('input JSON must be an object');
    }
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`context-packet: ${message}\n`);
    process.exitCode = 2;
  }
}

const isMain = process.argv[1] !== undefined
  && fileURLToPath(import.meta.url) === resolve(process.argv[1]);
if (isMain) {
  runCli();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const modulePath = fileURLToPath(new URL('../context-packet.js', import.meta.url));
const section = (id, text, priority = 0, required = false) => ({ id, text, priority, required });
const frame = (value) => `### ${JSON.stringify(value.id)}\n${value.text}\n`;
const cost = (value) => Buffer.byteLength(frame(value), 'utf8');

function cli(args) {
  return spawnSync(process.execPath, [modulePath, ...args], { encoding: 'utf8' });
}

function withTempDir(fn) {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  try {
    return fn(directory);
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
}

test('validates the complete API input, including zero-budget omitted entries', () => {
  const invalidCalls = [
    () => packContext(null, 0),
    () => packContext({}, 0),
    () => packContext([], -1),
    () => packContext([], 1.5),
    () => packContext([], Number.MAX_SAFE_INTEGER + 1),
    () => packContext([], '0'),
    () => packContext([null], 0),
    () => packContext([[]], 0),
    () => packContext(['x'], 0),
    () => packContext([{ text: '', priority: 0, required: false }], 0),
    () => packContext([{ id: '', text: '', priority: 0, required: false }], 0),
    () => packContext([{ id: 'x', priority: 0, required: false }], 0),
    () => packContext([{ id: 'x', text: 1, priority: 0, required: false }], 0),
    () => packContext([{ id: 'x', text: '', priority: -1, required: false }], 0),
    () => packContext([{ id: 'x', text: '', priority: 1.1, required: false }], 0),
    () => packContext([{ id: 'x', text: '', priority: Number.MAX_SAFE_INTEGER + 1, required: false }], 0),
    () => packContext([{ id: 'x', text: '', priority: 0 }], 0),
    () => packContext([{ id: 'x', text: '', priority: 0, required: 0 }], 0),
    () => packContext([section('same', ''), section('same', '')], 0)
  ];
  for (const call of invalidCalls) assert.throws(call, Error);

  const sparse = new Array(2);
  sparse[1] = section('present', '');
  assert.throws(() => packContext(sparse, 0), Error);
});

test('accepts exact, unusual and case-sensitive unique IDs with exact JSON/UTF-8 framing', () => {
  const values = [
    section(' ', 'é'), section('雪', 'line\r\n'), section('a\nb', ''),
    section('\0', 'nul-id'), section('__proto__', 'safe'), section('Case', ''), section('case', '')
  ];
  const expected = values.map(frame).join('');
  const result = packContext(values, Buffer.byteLength(expected, 'utf8'));
  assert.deepEqual(result, {
    text: expected,
    bytes: Buffer.byteLength(expected, 'utf8'),
    included: values.map(({ id }) => id),
    omitted: []
  });
  assert.equal(Buffer.byteLength(result.text, 'utf8'), result.bytes);
});

test('does not mutate input objects or array and ignores unknown fields', () => {
  const first = Object.freeze({ ...section('first', 'x', 2), ignored: { value: 1 } });
  const second = Object.freeze(section('second', 'y', 1));
  const input = Object.freeze([first, second]);
  const before = JSON.stringify(input);
  assert.deepEqual(packContext(input, 100).included, ['first', 'second']);
  assert.equal(JSON.stringify(input), before);
});

test('required original order precedes optional priority/tie order', () => {
  const values = [
    section('low-required', 'r1', 0, true),
    section('tie-first', 'o1', 9),
    section('high-required', 'r2', 99, true),
    section('tie-second', 'o2', 9),
    section('lower', 'o3', 1)
  ];
  assert.deepEqual(packContext(values, 1000).included,
    ['low-required', 'high-required', 'tie-first', 'tie-second', 'lower']);
});

test('optional packing skips oversized frames and reports omissions in original order', () => {
  const largeFirst = section('large-first', 'x'.repeat(80), 8);
  const fitting = section('fitting', 'ok', 7);
  const largeLast = section('large-last', 'y'.repeat(80), 10);
  const required = section('required', 'must', 999, true);
  const budget = cost(required) + cost(fitting);
  const result = packContext([largeFirst, fitting, largeLast, required], budget);
  assert.deepEqual(result.included, ['required', 'fitting']);
  assert.deepEqual(result.omitted, ['large-first', 'large-last']);
  assert.equal(result.bytes, budget);
  assert.equal(result.text, frame(required) + frame(fitting));
});

test('empty, omitted, exact-fit, and required-overflow boundaries', () => {
  assert.deepEqual(packContext([], 0), { text: '', bytes: 0, included: [], omitted: [] });
  const optional = section('optional', 'x');
  assert.deepEqual(packContext([optional], 0), {
    text: '', bytes: 0, included: [], omitted: ['optional']
  });
  assert.equal(packContext([optional], cost(optional)).text, frame(optional));
  assert.throws(() => packContext([section('required', '', 0, true)], 0), Error);
});

test('CLI success has exact stdout, empty stderr, and status zero', () => withTempDir((directory) => {
  const input = join(directory, 'input.json');
  const value = section('雪', 'é', 1, true);
  writeFileSync(input, JSON.stringify({ sections: [value], maxBytes: cost(value), ignored: true }));
  const expected = packContext([value], cost(value));
  const result = cli([input]);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, `${JSON.stringify(expected)}\n`);
  assert.equal(result.stderr, '');
}));

test('CLI failures use exit 2, no stdout, and nonempty stderr', () => withTempDir((directory) => {
  const malformed = join(directory, 'malformed.json');
  const invalid = join(directory, 'invalid.json');
  const overflow = join(directory, 'overflow.json');
  writeFileSync(malformed, '{');
  writeFileSync(invalid, JSON.stringify({ sections: [section('x', '', -1)], maxBytes: 0 }));
  writeFileSync(overflow, JSON.stringify({ sections: [section('r', 'x', 0, true)], maxBytes: 0 }));
  const cases = [[], [invalid, 'extra'], [join(directory, 'missing.json')], [malformed], [invalid], [overflow]];
  for (const args of cases) {
    const result = cli(args);
    assert.equal(result.status, 2, `args: ${JSON.stringify(args)}`);
    assert.equal(result.stdout, '');
    assert.notEqual(result.stderr, '');
  }
}));

test('importing the module does not execute the CLI', () => {
  const script = `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)}; process.stdout.write('imported\\n')`;
  const result = spawnSync(process.execPath, ['--input-type=module', '--eval', script], { encoding: 'utf8' });
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'imported\n');
  assert.equal(result.stderr, '');
});

