import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

function invalid(message) {
  throw new Error(message);
}

/**
 * Select complete, framed context sections within a UTF-8 byte budget.
 *
 * @param {Array<{id:string,text:string,priority:number,required:boolean}>} sections
 * @param {number} maxBytes
 * @returns {{text:string,bytes:number,included:string[],omitted:string[]}}
 */
export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    invalid('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    invalid('sections must be an array');
  }

  const seenIds = new Set();
  const validated = [];
  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) {
      invalid(`sections must be dense (missing index ${index})`);
    }
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      invalid(`section at index ${index} must be a non-null, non-array object`);
    }
    if (typeof section.id !== 'string' || section.id.length === 0) {
      invalid(`section at index ${index} has an invalid id`);
    }
    if (seenIds.has(section.id)) {
      invalid(`duplicate section id: ${JSON.stringify(section.id)}`);
    }
    if (typeof section.text !== 'string') {
      invalid(`section at index ${index} has invalid text`);
    }
    if (!Number.isSafeInteger(section.priority) || section.priority < 0) {
      invalid(`section at index ${index} has invalid priority`);
    }
    if (typeof section.required !== 'boolean') {
      invalid(`section at index ${index} has invalid required flag`);
    }

    seenIds.add(section.id);
    const frame = `### ${JSON.stringify(section.id)}\n${section.text}\n`;
    validated.push({
      id: section.id,
      priority: section.priority,
      required: section.required,
      index,
      frame,
      bytes: Buffer.byteLength(frame, 'utf8')
    });
  }

  const required = validated.filter((section) => section.required);
  const requiredBytes = required.reduce((total, section) => total + section.bytes, 0);
  if (requiredBytes > maxBytes) {
    invalid('required sections exceed maxBytes');
  }

  const optional = validated
    .filter((section) => !section.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);
  const selected = [...required];
  let bytes = requiredBytes;
  const includedOptional = new Set();
  for (const section of optional) {
    if (section.bytes <= maxBytes - bytes) {
      selected.push(section);
      includedOptional.add(section.index);
      bytes += section.bytes;
    }
  }

  return {
    text: selected.map((section) => section.frame).join(''),
    bytes,
    included: selected.map((section) => section.id),
    omitted: validated
      .filter((section) => !section.required && !includedOptional.has(section.index))
      .map((section) => section.id)
  };
}

function runCli() {
  try {
    if (process.argv.length !== 3) {
      invalid('usage: node context-packet.js INPUT_JSON_FILE');
    }
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      invalid('input JSON must be an object');
    }
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`context-packet: ${message}\n`);
    process.exitCode = 2;
  }
}

const isMain = process.argv[1] !== undefined
  && fileURLToPath(import.meta.url) === resolve(process.argv[1]);
if (isMain) {
  runCli();
}

